_RESEARCH_PATHS = {
    "research.web-research": "/agent-cli/research/web-research",
    "research.social-media-search": "/agent-cli/research/social-media-search",
    "research.community-search": "/agent-cli/research/community-search",
    "research.visual-analyze": "/agent-cli/research/visual-analyze",
}


async def _execute_research(ctx: CommandContext) -> Any:
    if not ctx.workspace_id:
        raise RuntimeError("missing_workspace")
    return agent_domain_result(
        await ctx.api_data(
            ctx.cfg,
            "POST",
            _RESEARCH_PATHS[ctx.spec.schema_name],
            json_body={"workspace_id": ctx.workspace_id, "payload": ctx.arguments},
        )
    )


